  var STORAGE_KEY='ag_ui_locale';
  var SUPPORTED=['es','en','pt'];
  var listeners=[];
  var observer=null;
  var translating=false;

  function safeGet(k){ try{return global.localStorage?global.localStorage.getItem(k):null;}catch(e){return null;} }
  function safeSet(k,v){ try{if(global.localStorage)global.localStorage.setItem(k,v);}catch(e){} }
  function queryLocale(){
    try{ var v=new URL(global.location.href).searchParams.get('lang'); return SUPPORTED.indexOf(v)>-1?v:null; }catch(e){return null;}
  }
  function initialLocale(){
    var q=queryLocale(); if(q){safeSet(STORAGE_KEY,q);return q;}
    var s=safeGet(STORAGE_KEY); if(SUPPORTED.indexOf(s)>-1)return s;
    var nav=(global.navigator&&global.navigator.language||'').toLowerCase();
    if(nav.indexOf('pt')===0)return 'pt';
    return nav && nav.indexOf('es')!==0 ? 'en' : 'es';
  }
  var locale=initialLocale();

  function localeTag(loc){ var l=loc||locale; if(l==='en')return 'en-US'; if(l==='pt')return 'pt-BR'; return 'es-AR'; }
  function formatDate(value, options, loc){
    var d=value instanceof Date?value:new Date(value);
    if(isNaN(d.getTime()))return '';
    return d.toLocaleDateString(localeTag(loc), options || {day:'numeric',month:'long',year:'numeric'});
  }
  function formatTime(value, options, loc){
    var d=value instanceof Date?value:new Date(value);
    if(isNaN(d.getTime()))return '';
    return d.toLocaleTimeString(localeTag(loc), options || {hour:'2-digit',minute:'2-digit'});
  }
  function formatDateTime(value, options, loc){
    var d=value instanceof Date?value:new Date(value);
    if(isNaN(d.getTime()))return '';
    return d.toLocaleString(localeTag(loc), options);
  }
  function formatNumber(value, options, loc){
    try{return Number(value).toLocaleString(localeTag(loc),options||{});}catch(e){return String(value);}
  }

  function preserveSpace(original,replacement){
    var lead=(original.match(/^\s*/)||[''])[0], trail=(original.match(/\s*$/)||[''])[0];
    return lead+replacement+trail;
  }
  function monthWords(s,from,to){
    var es=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
    var en=['January','February','March','April','May','June','July','August','September','October','November','December'];
    var pt=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
    var MAP={es:es,en:en,pt:pt};
    var f=MAP[from]||es, dest=MAP[to]||en;
    if(f===dest)return s;
    for(var i=0;i<12;i++) s=s.replace(new RegExp('\\b'+f[i]+'\\b','gi'),dest[i]);
    return s;
  }

